import { test } from "node:test";
import assert from "node:assert/strict";
import { InMemoryBroker } from "../src/queue/broker.ts";
import { DedupStore, PointsLedger, publishPurchase } from "../src/loyalty/purchases.ts";
import { PointsConsumer } from "../src/loyalty/pointsConsumer.ts";

const DAY = 86_400_000;

function setup() {
    const broker = new InMemoryBroker();
    const ledger = new PointsLedger();
    const clock = { now: Date.parse("2026-11-27T09:00:00Z") };
    const consumer = new PointsConsumer(broker, ledger, new DedupStore(DAY), () => clock.now);
    return { broker, ledger, clock, consumer };
}

test("a purchase earns one point per whole dollar", async () => {
    const { broker, ledger, consumer } = setup();
    await publishPurchase(broker, { orderId: "o-1", memberId: "m-42", amountCents: 12_999 });
    await consumer.drain();
    assert.equal(ledger.balances.get("m-42"), 129);
    assert.equal(broker.depth(), 0);
});

test("a delivery that comes back after a crash before the ack is not awarded again", async () => {
    const { broker, ledger, consumer } = setup();
    await publishPurchase(broker, { orderId: "o-1", memberId: "m-42", amountCents: 5_000 });
    const [msg] = await broker.receive(1);
    const ack = broker.ack;
    broker.ack = async () => { throw new Error("connection reset"); };
    await assert.rejects(consumer.handle(msg));
    broker.ack = ack;
    broker.expireInFlight();
    await consumer.drain();
    assert.equal(ledger.balances.get("m-42"), 50);
    assert.equal(consumer.stats.duplicates, 1);
});

test("an order checkout re-published after a timeout earns points once", async () => {
    const { broker, ledger, consumer } = setup();
    broker.timeoutsAfterAccept = 1;
    await publishPurchase(broker, { orderId: "o-7", memberId: "m-42", amountCents: 20_000 });
    await consumer.drain();
    console.log("balance for one $200 order:", ledger.balances.get("m-42"), consumer.stats);
    assert.equal(ledger.balances.get("m-42"), 200);
    assert.equal(consumer.stats.duplicates, 1);
});

test("two different orders for the same amount both earn points", async () => {
    const { broker, ledger, consumer } = setup();
    await publishPurchase(broker, { orderId: "o-1", memberId: "m-42", amountCents: 1_000 });
    await publishPurchase(broker, { orderId: "o-2", memberId: "m-42", amountCents: 1_000 });
    await consumer.drain();
    assert.equal(ledger.balances.get("m-42"), 20);
    assert.equal(consumer.stats.duplicates, 0);
});

test("an award that failed is retried rather than treated as a duplicate", async () => {
    const { broker, ledger, consumer } = setup();
    ledger.failNextAwards = 2;
    await publishPurchase(broker, { orderId: "o-3", memberId: "m-9", amountCents: 7_550 });
    await consumer.drain();
    assert.equal(ledger.balances.get("m-9"), 75);
    assert.deepEqual(consumer.stats, { awarded: 1, duplicates: 0, failed: 2 });
});

test("a Black Friday session with flaky publishes and a flaky ledger balances exactly", async () => {
    const { broker, ledger, consumer } = setup();
    const orders = [
        { orderId: "o-10", memberId: "m-1", amountCents: 4_000 },
        { orderId: "o-11", memberId: "m-2", amountCents: 9_900 },
        { orderId: "o-12", memberId: "m-1", amountCents: 15_050 },
    ];
    for (const o of orders) {
        broker.timeoutsAfterAccept = o.orderId === "o-11" ? 0 : 2;
        await publishPurchase(broker, o);
    }
    ledger.failNextAwards = 1;
    await consumer.drain();
    assert.deepEqual(Object.fromEntries(ledger.balances), { "m-1": 190, "m-2": 99 });
    assert.equal(broker.depth(), 0);
});

test("once the dedup window has passed, a key can be claimed again", () => {
    const store = new DedupStore(DAY);
    const t0 = Date.parse("2026-11-27T09:00:00Z");
    assert.equal(store.claim("purchase:o-1", t0), true);
    assert.equal(store.claim("purchase:o-1", t0 + DAY - 1), false);
    assert.equal(store.claim("purchase:o-1", t0 + DAY), true);
});
